{"type":"message_start","message":{"role":"user","content":[{"type":"text","text":"{\"schema\": \"aos-material-review/v1\", \"owner\": \"codex-01a107a2-e9e4-7670-bc44-1144fa9b27e2\", \"kind\": \"quality\", \"response_contract\": {\"format\": \"Return one RAW JSON object with no markdown/backticks. Each finding.claim must copy an exact entire claims string, including punctuation. assessment ONLY supported, contradicted, insufficient. Copy request identity/baseline exactly.\", \"required_fields\": [\"request_id\", \"task_id\", \"owner\", \"kind\", \"baseline\", \"verdict\", \"findings\", \"next_safe_step\"], \"findings_required_fields\": [\"claim\", \"evidence\", \"assessment\"], \"next_safe_step\": \"nonempty string; required even for PASS\"}, \"task_id\": \"qyh-native-readmodel-installed-gate-20261013\", \"request_id\": \"qyh-native-readmodel-installed-gate-20261013-adapter-r1\", \"baseline\": {\"head\": \"98642f8bdde5f837310f281efed8fce2b0a8d1aa\", \"authority_revision\": \"AOS-002011\", \"files\": {\".evidence/qyh-native-readmodel-installed-gate-20261013/review-material-0.txt\": \"4270152eb6365fe1d2b81df972b26252fcd3f741e45fb928b34904dc16b178fb\", \".evidence/qyh-native-readmodel-installed-gate-20261013/review-material-1.txt\": \"eeb97b4ee29bbe200596ec589038b6cf1bf85b66a28aab208f38892ac33b159a\", \".evidence/qyh-native-readmodel-installed-gate-20261013/review-material-2.txt\": \"698cd181755cb4fc45f26e1ed367d4af9074eb20a41f980dc15163e23be69a0f\", \".evidence/qyh-native-readmodel-installed-gate-20261013/review-material-3.txt\": \"ece044e8bb090fabebcef075b58e7a2da0d89828846037186efbdb53d6072f7b\", \".evidence/qyh-native-readmodel-installed-gate-20261013/review-material-4.txt\": \"c3dc2a9661a8a4184d08bfd005b141729add24a111641cdead8280e137048751\"}}, \"materials\": {\".evidence/qyh-native-readmodel-installed-gate-20261013/review-material-0.txt\": \"\\\"\\\"\\\"GET admission candidate over a current, signed, explicitly selected installation.\\n\\nThis adapter does not activate HTTP routes or grant runtime readiness. Legacy\\nadmission is preserved; selected installed assets require actual exact scope grants.\\n\\\"\\\"\\\"\\nfrom __future__ import annotations\\n\\nfrom aos_api.asset_registry.errors import AssetNotFoundError\\nfrom aos_api.ecommerce_workshop_contracts import WorkshopDependencyType\\n\\n\\nclass EcommerceWorkshopReadCatalog:\\n    def __init__(self, *, legacy, installed) -> None:\\n        self._legacy = legacy\\n        self._installed = installed\\n\\n    def get_readiness(self, **scope):\\n        try:\\n            return self._legacy.get_readiness(**scope)\\n        except AssetNotFoundError:\\n            # Integrity, signature and availability errors never permit fallback.\\n            pass\\n        result = self._installed.get_readiness(**scope)\\n        item = result.item\\n        installation = item.installation_ref\\n        required = set(item.permissions.data_scopes)\\n        expected_revision = (\\n            f'installation:{installation.revision}/lock:{installation.lock_revision}'\\n        )\\n        granted = {\\n            ref.resource_id for ref in item.dependency_refs\\n            if ref.resource_type == 'DataScopeGrant'\\n            and ref.revision == expected_revision\\n            and ref.content_hash == installation.lock_hash\\n            and ref.authority == 'postgres:bundle_composition_lock'\\n        }\\n        permitted_gap_types = {\\n            WorkshopDependencyType.OBJECT,\\n            WorkshopDependencyType.CAPABILITY,\\n            WorkshopDependencyType.AIP_FEATURE,\\n        }\\n        disallowed = any(\\n            blocker.dependency_type not in permitted_gap_types\\n            and not (\\n                blocker.dependency_type == WorkshopDependencyType.INSTALLATION\\n                and blocker.reason_code == 'INSTALLED_ASSET_READONLY'\\n                and blocker.dependency_id == installation.installation_id\\n            )\\n            for blocker in item.blockers\\n        )\\n        if 'ecommerce.workshop.read' not in required or not required <= granted or disallowed:\\n            raise AssetNotFoundError('Workshop module is not installed for scoped reading')\\n        # Keep the original disabled state and every runtime/authority gap intact.\\n        return result\\n\", \".evidence/qyh-native-readmodel-installed-gate-20261013/review-material-1.txt\": \"\\\"\\\"\\\"Candidate read gate tests; no HTTP activation or real database effects.\\\"\\\"\\\"\\nfrom types import SimpleNamespace\\nimport pytest\\nfrom aos_api.asset_registry.errors import AssetNotFoundError, RegistryIntegrityCorruptError\\nfrom tests.asset_registry.test_ecommerce_installed_readonly_catalog import catalog\\nfrom tests.asset_registry.test_ecommerce_workshop_catalog import _active, _persisted, _loaded_growth\\n\\nARGS = dict(module_id='ecommerce.customer', org_id='org-org', project_id='dev-project', roles=['operator'], markings=['public'])\\n\\nclass MissingLegacy:\\n    def get_readiness(self, **kwargs):\\n        raise AssetNotFoundError('Workshop module is not installed')\\n\\ndef make(*, granted=True):\\n    from aos_api.ecommerce_workshop_read_catalog import EcommerceWorkshopReadCatalog\\n    loaded = _loaded_growth()\\n    scopes = sorted({s for m in loaded.workshop_modules for s in m.permissions.data_scopes}) if granted else []\\n    installed, source = catalog([_active(_persisted(loaded), target_data_scopes=scopes)])\\n    return EcommerceWorkshopReadCatalog(legacy=MissingLegacy(), installed=installed), source\\n\\ndef test_exact_granted_installed_asset_can_pass_read_gate_without_runtime_promotion():\\n    c, _ = make()\\n    result = c.get_readiness(**ARGS)\\n    assert result.item.module_id == ARGS['module_id']\\n    assert result.item.readiness.value == 'disabled'\\n    assert any(b.reason_code == 'INSTALLED_ASSET_READONLY' for b in result.item.blockers)\\n\\ndef test_declared_scope_without_current_lock_grant_is_rejected():\\n    c, _ = make(granted=False)\\n    with pytest.raises(AssetNotFoundError): c.get_readiness(**ARGS)\\n\\n@pytest.mark.parametrize('changes', [{'org_id':'dev-org'}, {'project_id':'other'}])\\ndef test_cross_tenant_denied_before_candidate_source_access(changes):\\n    c, source = make()\\n    with pytest.raises(AssetNotFoundError): c.get_readiness(**{**ARGS, **changes})\\n    assert source.calls == []\\n\\ndef test_installation_revocation_is_checked_each_time():\\n    c, source = make()\\n    c.get_readiness(**ARGS)\\n    source.rows = []\\n    with pytest.raises(AssetNotFoundError): c.get_readiness(**ARGS)\\n    assert len(source.calls) == 2\\n\\ndef test_legacy_success_is_preserved_without_reading_candidate():\\n    from aos_api.ecommerce_workshop_read_catalog import EcommerceWorkshopReadCatalog\\n    sentinel = object()\\n    c = EcommerceWorkshopReadCatalog(legacy=SimpleNamespace(get_readiness=lambda **kw: sentinel), installed=None)\\n    assert c.get_readiness(**ARGS) is sentinel\\n\\ndef test_legacy_integrity_error_never_falls_back():\\n    from aos_api.ecommerce_workshop_read_catalog import EcommerceWorkshopReadCatalog\\n    def corrupt(**kwargs): raise RegistryIntegrityCorruptError()\\n    c = EcommerceWorkshopReadCatalog(legacy=SimpleNamespace(get_readiness=corrupt), installed=None)\\n    with pytest.raises(RegistryIntegrityCorruptError): c.get_readiness(**ARGS)\\n\\ndef test_grant_reference_must_match_current_exact_lock():\\n    c, _ = make()\\n    result = c.get_readiness(**ARGS)\\n    refs = [r.model_copy(update={'content_hash':'sha256:'+'f'*64}) if r.resource_type == 'DataScopeGrant' else r for r in result.item.dependency_refs]\\n    item = result.item.model_copy(update={'dependency_refs':refs})\\n    c._installed = SimpleNamespace(get_readiness=lambda **kw: result.model_copy(update={'item':item}))\\n    with pytest.raises(AssetNotFoundError): c.get_readiness(**ARGS)\\n\\n@pytest.mark.parametrize('field,value', [('revision','installation:4/lock:1'), ('authority','client:declaration')])\\ndef test_grant_from_another_revision_or_authority_is_rejected(field, value):\\n    c, _ = make()\\n    result = c.get_readiness(**ARGS)\\n    refs = [r.model_copy(update={field:value}) if r.resource_type == 'DataScopeGrant' else r for r in result.item.dependency_refs]\\n    c._installed = SimpleNamespace(get_readiness=lambda **kw: result.model_copy(update={'item':result.item.model_copy(update={'dependency_refs':refs})}))\\n    with pytest.raises(AssetNotFoundError): c.get_readiness(**ARGS)\\n\\ndef test_candidate_bundle_content_drift_is_not_hidden_by_fallback():\\n    from dataclasses import replace\\n    c, source = make()\\n    row = source.rows[0]\\n    source.rows = [replace(row, bundle=replace(row.bundle, content_hash='sha256:'+'f'*64))]\\n    with pytest.raises(RegistryIntegrityCorruptError): c.get_readiness(**ARGS)\\n\\n@pytest.mark.parametrize('changes', [{'roles':[]}, {'markings':[]}])\\ndef test_original_role_and_marking_filter_still_denies_installed_candidate(changes):\\n    c, _ = make()\\n    loaded = _loaded_growth()\\n    modules = [m.model_copy(update={'permissions':m.permissions.model_copy(update={'roles':['operator'],'markings':['public']})}) for m in loaded.workshop_modules]\\n    # Permission boundary fixture only, not independently signed production proof.\\n    c._installed._loader = SimpleNamespace(load=lambda ref: loaded.model_copy(update={'workshop_modules':modules}))\\n    with pytest.raises(AssetNotFoundError): c.get_readiness(**{**ARGS, **changes})\\n\\ndef test_metadata_projection_with_registry_blocker_cannot_open_business_read():\\n    from aos_api.ecommerce_workshop_contracts import WorkshopReadinessBlocker\\n    c, _ = make()\\n    result = c.get_readiness(**ARGS)\\n    blocker = WorkshopReadinessBlocker(dependencyType='registry', dependencyId='bundle', state='blocked', reasonCode='REGISTRY_REVOKED', recoverable=False, requiredAction='Current registration required')\\n    c._installed = SimpleNamespace(get_readiness=lambda **kw: result.model_copy(update={'item':result.item.model_copy(update={'blockers':[*result.item.blockers,blocker]})}))\\n    with pytest.raises(AssetNotFoundError): c.get_readiness(**ARGS)\\n\", \".evidence/qyh-native-readmodel-installed-gate-20261013/review-material-2.txt\": \"# 下一波：原八台只读read-model安装门调查\\n\\nRules：用户初心、231、上位双侧增长产品与恢复方案。八页可点击不是首链；现有404必须调查真实原因，不因预算未续期而把所有读取归因预算。已有签名ACTIVE5八模块明确授ecommerce.workshop.read（原投影没有DATA_SCOPE_NOT_GRANTED）；旧CatalogDependency legacy-only排除所有当前runtime包。\\n\\n第1/8：复习上位产品与当前authority2011，代码预检已交付98642f8但不授预算/运行。第2/8文件计划：新增ecommerce_workshop_read_catalog.py（仅若审计证明GET可独立于runtime执行，以原签名/安装/真实data-scope为读取条件），routers/ecommerce_workshop.py只允许明确审核的GET注入ReadCatalogDependency；新增test_ecommerce_workshop_read_catalog.py证明无身份/租户/锁/签名/数据scope拒绝，POST继续旧业务依赖及原执行门。\\n\\n先在同轮实际审计8个GET与默认reader构造：仅AOS当前已保留数据/明确unknown来源，禁止触发外部商城/Provider/Source探测；如果某reader可能外部请求，该route不纳入本波。先限定root8，辅助/private GET另逐项审计。不改变legacy来源谓词、不伪造runtime-ready/UI session/Owner/审批，不返回mock数据或把None转0。写代码前要记录具体审计与细化方案，再RED、最小实现、专项/累计、真实页面、独立冻结代码复审、Delivery/上下文及下一波。目标是让真实安装状态与read-model缺口正确反映，真实数据/天然首链仍独立验收。\\n\\n## 第2/8细化（2026-10-13，本轮规则与候选）\\nRules：已复习 aos-engineering-delivery、当前01/06 authority2011、231上下文与产品双侧增长方案。唯一m1写者；Task同owner Lease至10:47UTC有效；用户dirty不覆盖；本aos-2不重启。候选一：已登记GET安装读取门（无真实库写、无外部请求依赖）；候选二：已登记预算续期有界consumer（需原真实maker/checker与当前锁再验，不能复用安装审批）。本轮选择候选一。\\n\\n具体目录：services/aos-api/aos_api/ecommerce_workshop_read_catalog.py；services/aos-api/tests/test_ecommerce_workshop_read_catalog.py；后续审计完成才改services/aos-api/aos_api/routers/ecommerce_workshop.py。\\n\\n已实际复核：Analyst SourceReadiness只读本库meta_pipeline/meta_source/meta_schedule_run/ecom_object/obj_instance/capability及本地policy文件，无源探测；Customer读本库保留自然run/count；ContentCampaign read_snapshot使用read_connect_factory；Creator各list使用read_connect_factory；TaskCockpit read_core显式REPEATABLE READ READ ONLY。Media根read还经过lifecycle、publish._compose及多个list/get，仍需对其完整传递调用作审计；Operations各本库reader亦需补全。不能因方法名为read就宣称无副作用。\\n\\n本轮先实现独立适配器，尚不接任何HTTP route：原legacy get_readiness成功原样保留；仅AssetNotFound才查显式selected安装目录；完整复用原签名/锁/hash/角色/marking/撤销检查；selected fallback要求每个声明dataScope都有本安装同lock的DataScopeGrant，禁止只凭module.permissions宣称授权；非object/capability/aip未知或INSTALLED_ASSET_READONLY的其他blocker均拒绝；不提升disabled/readiness、不缓存安装。返回not found隐去未授权模块；原目录、POST及服务reader无改动。专项包括真实本地bundle解析fixture、无scope、撤销、跨tenant、hash漂移、legacy错误不回退和legacy成功不改变。此阶段只证明读取门候选，不证明HTTP数据/8页面/首链。最终route仍待安全审计和单独RED。\\n\\n第3/8：8缺模块RED已复现后新增纯读取适配器；第4/8：专项与原目录、runtime目录及原HTTP邻接结果见verification-candidate.json。路由字节与HEAD一致，未激活GET、未重启、未改真库、未运行Provider。Media committed HEAD传递调用已按精确方法/hash提取，仍需复核_bundle/_view/_decision/_job等递归helper，不可把调用提取当无效果证明。第5～8步及HTTP接线仍待继续；Task保持ACTIVE，不声称页面或业务恢复完成。\\n\", \".evidence/qyh-native-readmodel-installed-gate-20261013/review-material-3.txt\": \"..................................................................       [100%]\\n=============================== warnings summary ===============================\\nservices/aos-api/aos_api/media_set.py:70\\n  /Users/ddt/work/projects/ai_agent/aos-platform/services/aos-api/aos_api/media_set.py:70: UserWarning: Field name \\\"schema\\\" in \\\"MediaSet\\\" shadows an attribute in parent \\\"BaseModel\\\"\\n    class MediaSet(BaseModel):\\n\\nservices/aos-api/aos_api/materialized_access_control.py:130\\n  /Users/ddt/work/projects/ai_agent/aos-platform/services/aos-api/aos_api/materialized_access_control.py:130: UserWarning: Field name \\\"schema\\\" in \\\"AgentTool\\\" shadows an attribute in parent \\\"BaseModel\\\"\\n    class AgentTool(BaseModel):\\n\\nservices/aos-api/aos_api/routers/materialized_access_control.py:83\\n  /Users/ddt/work/projects/ai_agent/aos-platform/services/aos-api/aos_api/routers/materialized_access_control.py:83: UserWarning: Field name \\\"schema\\\" in \\\"CreateAgentToolRequest\\\" shadows an attribute in parent \\\"BaseModel\\\"\\n    class CreateAgentToolRequest(BaseModel):\\n\\nservices/aos-api/aos_api/aip_logic_dry_run_executor.py:45\\n  /Users/ddt/work/projects/ai_agent/aos-platform/services/aos-api/aos_api/aip_logic_dry_run_executor.py:45: UserWarning: Field name \\\"schema\\\" in \\\"_InputConfig\\\" shadows an attribute in parent \\\"_Config\\\"\\n    class _InputConfig(_Config):\\n\\nservices/aos-api/aos_api/phase5_pipeline_engine.py:126\\n  /Users/ddt/work/projects/ai_agent/aos-platform/services/aos-api/aos_api/phase5_pipeline_engine.py:126: UserWarning: Field name \\\"schema\\\" in \\\"Dataset\\\" shadows an attribute in parent \\\"BaseModel\\\"\\n    class Dataset(BaseModel):\\n\\nservices/aos-api/aos_api/routers/phase5_datasets.py:32\\n  /Users/ddt/work/projects/ai_agent/aos-platform/services/aos-api/aos_api/routers/phase5_datasets.py:32: UserWarning: Field name \\\"schema\\\" in \\\"CreateDatasetRequest\\\" shadows an attribute in parent \\\"BaseModel\\\"\\n    class CreateDatasetRequest(BaseModel):\\n\\nservices/aos-api/.venv/lib/python3.11/site-packages/fastapi/testclient.py:1\\n  /Users/ddt/work/projects/ai_agent/aos-platform/services/aos-api/.venv/lib/python3.11/site-packages/fastapi/testclient.py:1: StarletteDeprecationWarning: Using `httpx` with `starlette.testclient` is deprecated; install `httpx2` instead.\\n    from starlette.testclient import TestClient as TestClient  # noqa\\n\\n-- Docs: https://docs.pytest.org/en/stable/how-to/capture-warnings.html\\n66 passed, 7 warnings in 4.49s\\n\", \".evidence/qyh-native-readmodel-installed-gate-20261013/review-material-4.txt\": \"\\\"\\\"\\\"Signed installed-asset viewing, separate from business/runtime admission.\\\"\\\"\\\"\\nfrom __future__ import annotations\\nfrom uuid import UUID\\n\\nfrom aos_api.ecommerce_workshop_catalog import EcommerceWorkshopCatalog\\nfrom aos_api.ecommerce_workshop_contracts import (\\n    WorkshopDependencyState, WorkshopDependencyType, WorkshopReadiness,\\n    WorkshopReadinessBlocker,\\n)\\n\\n\\nclass _SelectedInstalledSource:\\n    def __init__(self, source, *, installation_id: str, org_id: str, project_id: str):\\n        if str(UUID(installation_id)) != installation_id:\\n            raise ValueError('Canonical installation UUID required')\\n        if not org_id.strip() or not project_id.strip():\\n            raise ValueError('Explicit tenant required')\\n        self.source = source\\n        self.installation_id = installation_id\\n        self.org_id = org_id\\n        self.project_id = project_id\\n\\n    def read_active_bundles(self, *, org_id, project_id, markings):\\n        if (org_id, project_id) != (self.org_id, self.project_id):\\n            return ()\\n        # This remains candidate discovery. It grants no runtime/UI session.\\n        rows = self.source.read_runtime_candidate_bundles(\\n            org_id=org_id, project_id=project_id, markings=markings)\\n        return tuple(row for row in rows if row.installation_id == self.installation_id)\\n\\n\\nclass InstalledReadonlyWorkshopCatalog(EcommerceWorkshopCatalog):\\n    \\\"\\\"\\\"Reuse exact lock/signature/artifact/permission projection; always disabled.\\\"\\\"\\\"\\n    def __init__(self, *, source, loader, installation_id, org_id, project_id, clock=None):\\n        selected = _SelectedInstalledSource(source, installation_id=installation_id,\\n            org_id=org_id, project_id=project_id)\\n        super().__init__(source=selected, loader=loader, clock=clock)\\n\\n    def _project_modules(self, **kwargs):\\n        modules, cutoff = super()._project_modules(**kwargs)\\n        for module in modules:\\n            module.readiness = WorkshopReadiness.DISABLED\\n            module.blockers.append(WorkshopReadinessBlocker(\\n                dependencyType=WorkshopDependencyType.INSTALLATION,\\n                dependencyId=module.installation_ref.installation_id,\\n                state=WorkshopDependencyState.UNKNOWN,\\n                reasonCode='INSTALLED_ASSET_READONLY', recoverable=True,\\n                requiredAction='已安装页面可只读查看；业务执行仍须完成正式运行准入。'))\\n        return modules, cutoff\\n\\n\\nclass _EmptySource:\\n    def read_active_bundles(self, **kwargs):\\n        return ()\\n\\n\\ndef build_installed_readonly_catalog():\\n    \\\"\\\"\\\"Explicit server configuration; absent configuration discovers nothing.\\\"\\\"\\\"\\n    import json\\n    import os\\n    from pathlib import Path\\n    from aos_api.asset_registry.control_wiring import _allowlist_roots, _configured_trust_roots\\n    from aos_api.asset_registry.errors import RegistryIntegrityCorruptError\\n    from aos_api.asset_registry.manifest_loader import ManifestLoader\\n    from aos_api.asset_registry.workshop_catalog_source import PostgresWorkshopCatalogSource\\n    from aos_api.db import connect_read_only\\n\\n    raw = os.getenv('AOS_INSTALLED_READONLY_CATALOG')\\n    if not raw:\\n        return EcommerceWorkshopCatalog(source=_EmptySource(), loader=None)\\n    try:\\n        config = json.loads(raw)\\n        if not isinstance(config, dict) or set(config) != {'installationId', 'orgId', 'projectId'}:\\n            raise ValueError('Explicit bounded configuration required')\\n        if not all(isinstance(value, str) and value.strip() == value and value for value in config.values()):\\n            raise ValueError('Canonical configuration required')\\n        if not os.getenv('AOS_LOCAL_MANAGEMENT_OIDC_CONFIG') or not os.getenv('AOS_BUNDLE_ROOT'):\\n            raise ValueError('Management identity and signed source required')\\n        trust = _configured_trust_roots()\\n        if trust is None:\\n            raise ValueError('Explicit trust roots required')\\n        return InstalledReadonlyWorkshopCatalog(\\n            source=PostgresWorkshopCatalogSource(lambda: connect_read_only(inherit_scope=False)),\\n            loader=ManifestLoader(_allowlist_roots(repository_root=Path(__file__).resolve().parents[3]), trust_roots=trust),\\n            installation_id=config['installationId'], org_id=config['orgId'], project_id=config['projectId'])\\n    except (ValueError, TypeError, KeyError):\\n        raise RegistryIntegrityCorruptError() from None\\n\"}, \"claims\": [\"C1: The candidate preserves successful legacy admission and rejects fallback after a legacy integrity error. Its installed fallback requires every declared data scope to have a matching current lock grant; it preserves disabled readiness.\", \"C2: The isolated candidate and adjacent catalog/HTTP regression run passed 66 tests. No router was changed and no HTTP activation, real database write, runtime admission or business completion is claimed.\"]}"}],"timestamp":1791880874925}}
{"type":"message_end","message":{"role":"user","content":[{"type":"text","text":"{\"schema\": \"aos-material-review/v1\", \"owner\": \"codex-01a107a2-e9e4-7670-bc44-1144fa9b27e2\", \"kind\": \"quality\", \"response_contract\": {\"format\": \"Return one RAW JSON object with no markdown/backticks. Each finding.claim must copy an exact entire claims string, including punctuation. assessment ONLY supported, contradicted, insufficient. Copy request identity/baseline exactly.\", \"required_fields\": [\"request_id\", \"task_id\", \"owner\", \"kind\", \"baseline\", \"verdict\", \"findings\", \"next_safe_step\"], \"findings_required_fields\": [\"claim\", \"evidence\", \"assessment\"], \"next_safe_step\": \"nonempty string; required even for PASS\"}, \"task_id\": \"qyh-native-readmodel-installed-gate-20261013\", \"request_id\": \"qyh-native-readmodel-installed-gate-20261013-adapter-r1\", \"baseline\": {\"head\": \"98642f8bdde5f837310f281efed8fce2b0a8d1aa\", \"authority_revision\": \"AOS-002011\", \"files\": {\".evidence/qyh-native-readmodel-installed-gate-20261013/review-material-0.txt\": \"4270152eb6365fe1d2b81df972b26252fcd3f741e45fb928b34904dc16b178fb\", \".evidence/qyh-native-readmodel-installed-gate-20261013/review-material-1.txt\": \"eeb97b4ee29bbe200596ec589038b6cf1bf85b66a28aab208f38892ac33b159a\", \".evidence/qyh-native-readmodel-installed-gate-20261013/review-material-2.txt\": \"698cd181755cb4fc45f26e1ed367d4af9074eb20a41f980dc15163e23be69a0f\", \".evidence/qyh-native-readmodel-installed-gate-20261013/review-material-3.txt\": \"ece044e8bb090fabebcef075b58e7a2da0d89828846037186efbdb53d6072f7b\", \".evidence/qyh-native-readmodel-installed-gate-20261013/review-material-4.txt\": \"c3dc2a9661a8a4184d08bfd005b141729add24a111641cdead8280e137048751\"}}, \"materials\": {\".evidence/qyh-native-readmodel-installed-gate-20261013/review-material-0.txt\": \"\\\"\\\"\\\"GET admission candidate over a current, signed, explicitly selected installation.\\n\\nThis adapter does not activate HTTP routes or grant runtime readiness. Legacy\\nadmission is preserved; selected installed assets require actual exact scope grants.\\n\\\"\\\"\\\"\\nfrom __future__ import annotations\\n\\nfrom aos_api.asset_registry.errors import AssetNotFoundError\\nfrom aos_api.ecommerce_workshop_contracts import WorkshopDependencyType\\n\\n\\nclass EcommerceWorkshopReadCatalog:\\n    def __init__(self, *, legacy, installed) -> None:\\n        self._legacy = legacy\\n        self._installed = installed\\n\\n    def get_readiness(self, **scope):\\n        try:\\n            return self._legacy.get_readiness(**scope)\\n        except AssetNotFoundError:\\n            # Integrity, signature and availability errors never permit fallback.\\n            pass\\n        result = self._installed.get_readiness(**scope)\\n        item = result.item\\n        installation = item.installation_ref\\n        required = set(item.permissions.data_scopes)\\n        expected_revision = (\\n            f'installation:{installation.revision}/lock:{installation.lock_revision}'\\n        )\\n        granted = {\\n            ref.resource_id for ref in item.dependency_refs\\n            if ref.resource_type == 'DataScopeGrant'\\n            and ref.revision == expected_revision\\n            and ref.content_hash == installation.lock_hash\\n            and ref.authority == 'postgres:bundle_composition_lock'\\n        }\\n        permitted_gap_types = {\\n            WorkshopDependencyType.OBJECT,\\n            WorkshopDependencyType.CAPABILITY,\\n            WorkshopDependencyType.AIP_FEATURE,\\n        }\\n        disallowed = any(\\n            blocker.dependency_type not in permitted_gap_types\\n            and not (\\n                blocker.dependency_type == WorkshopDependencyType.INSTALLATION\\n                and blocker.reason_code == 'INSTALLED_ASSET_READONLY'\\n                and blocker.dependency_id == installation.installation_id\\n            )\\n            for blocker in item.blockers\\n        )\\n        if 'ecommerce.workshop.read' not in required or not required <= granted or disallowed:\\n            raise AssetNotFoundError('Workshop module is not installed for scoped reading')\\n        # Keep the original disabled state and every runtime/authority gap intact.\\n        return result\\n\", \".evidence/qyh-native-readmodel-installed-gate-20261013/review-material-1.txt\": \"\\\"\\\"\\\"Candidate read gate tests; no HTTP activation or real database effects.\\\"\\\"\\\"\\nfrom types import SimpleNamespace\\nimport pytest\\nfrom aos_api.asset_registry.errors import AssetNotFoundError, RegistryIntegrityCorruptError\\nfrom tests.asset_registry.test_ecommerce_installed_readonly_catalog import catalog\\nfrom tests.asset_registry.test_ecommerce_workshop_catalog import _active, _persisted, _loaded_growth\\n\\nARGS = dict(module_id='ecommerce.customer', org_id='org-org', project_id='dev-project', roles=['operator'], markings=['public'])\\n\\nclass MissingLegacy:\\n    def get_readiness(self, **kwargs):\\n        raise AssetNotFoundError('Workshop module is not installed')\\n\\ndef make(*, granted=True):\\n    from aos_api.ecommerce_workshop_read_catalog import EcommerceWorkshopReadCatalog\\n    loaded = _loaded_growth()\\n    scopes = sorted({s for m in loaded.workshop_modules for s in m.permissions.data_scopes}) if granted else []\\n    installed, source = catalog([_active(_persisted(loaded), target_data_scopes=scopes)])\\n    return EcommerceWorkshopReadCatalog(legacy=MissingLegacy(), installed=installed), source\\n\\ndef test_exact_granted_installed_asset_can_pass_read_gate_without_runtime_promotion():\\n    c, _ = make()\\n    result = c.get_readiness(**ARGS)\\n    assert result.item.module_id == ARGS['module_id']\\n    assert result.item.readiness.value == 'disabled'\\n    assert any(b.reason_code == 'INSTALLED_ASSET_READONLY' for b in result.item.blockers)\\n\\ndef test_declared_scope_without_current_lock_grant_is_rejected():\\n    c, _ = make(granted=False)\\n    with pytest.raises(AssetNotFoundError): c.get_readiness(**ARGS)\\n\\n@pytest.mark.parametrize('changes', [{'org_id':'dev-org'}, {'project_id':'other'}])\\ndef test_cross_tenant_denied_before_candidate_source_access(changes):\\n    c, source = make()\\n    with pytest.raises(AssetNotFoundError): c.get_readiness(**{**ARGS, **changes})\\n    assert source.calls == []\\n\\ndef test_installation_revocation_is_checked_each_time():\\n    c, source = make()\\n    c.get_readiness(**ARGS)\\n    source.rows = []\\n    with pytest.raises(AssetNotFoundError): c.get_readiness(**ARGS)\\n    assert len(source.calls) == 2\\n\\ndef test_legacy_success_is_preserved_without_reading_candidate():\\n    from aos_api.ecommerce_workshop_read_catalog import EcommerceWorkshopReadCatalog\\n    sentinel = object()\\n    c = EcommerceWorkshopReadCatalog(legacy=SimpleNamespace(get_readiness=lambda **kw: sentinel), installed=None)\\n    assert c.get_readiness(**ARGS) is sentinel\\n\\ndef test_legacy_integrity_error_never_falls_back():\\n    from aos_api.ecommerce_workshop_read_catalog import EcommerceWorkshopReadCatalog\\n    def corrupt(**kwargs): raise RegistryIntegrityCorruptError()\\n    c = EcommerceWorkshopReadCatalog(legacy=SimpleNamespace(get_readiness=corrupt), installed=None)\\n    with pytest.raises(RegistryIntegrityCorruptError): c.get_readiness(**ARGS)\\n\\ndef test_grant_reference_must_match_current_exact_lock():\\n    c, _ = make()\\n    result = c.get_readiness(**ARGS)\\n    refs = [r.model_copy(update={'content_hash':'sha256:'+'f'*64}) if r.resource_type == 'DataScopeGrant' else r for r in result.item.dependency_refs]\\n    item = result.item.model_copy(update={'dependency_refs':refs})\\n    c._installed = SimpleNamespace(get_readiness=lambda **kw: result.model_copy(update={'item':item}))\\n    with pytest.raises(AssetNotFoundError): c.get_readiness(**ARGS)\\n\\n@pytest.mark.parametrize('field,value', [('revision','installation:4/lock:1'), ('authority','client:declaration')])\\ndef test_grant_from_another_revision_or_authority_is_rejected(field, value):\\n    c, _ = make()\\n    result = c.get_readiness(**ARGS)\\n    refs = [r.model_copy(update={field:value}) if r.resource_type == 'DataScopeGrant' else r for r in result.item.dependency_refs]\\n    c._installed = SimpleNamespace(get_readiness=lambda **kw: result.model_copy(update={'item':result.item.model_copy(update={'dependency_refs':refs})}))\\n    with pytest.raises(AssetNotFoundError): c.get_readiness(**ARGS)\\n\\ndef test_candidate_bundle_content_drift_is_not_hidden_by_fallback():\\n    from dataclasses import replace\\n    c, source = make()\\n    row = source.rows[0]\\n    source.rows = [replace(row, bundle=replace(row.bundle, content_hash='sha256:'+'f'*64))]\\n    with pytest.raises(RegistryIntegrityCorruptError): c.get_readiness(**ARGS)\\n\\n@pytest.mark.parametrize('changes', [{'roles':[]}, {'markings':[]}])\\ndef test_original_role_and_marking_filter_still_denies_installed_candidate(changes):\\n    c, _ = make()\\n    loaded = _loaded_growth()\\n    modules = [m.model_copy(update={'permissions':m.permissions.model_copy(update={'roles':['operator'],'markings':['public']})}) for m in loaded.workshop_modules]\\n    # Permission boundary fixture only, not independently signed production proof.\\n    c._installed._loader = SimpleNamespace(load=lambda ref: loaded.model_copy(update={'workshop_modules':modules}))\\n    with pytest.raises(AssetNotFoundError): c.get_readiness(**{**ARGS, **changes})\\n\\ndef test_metadata_projection_with_registry_blocker_cannot_open_business_read():\\n    from aos_api.ecommerce_workshop_contracts import WorkshopReadinessBlocker\\n    c, _ = make()\\n    result = c.get_readiness(**ARGS)\\n    blocker = WorkshopReadinessBlocker(dependencyType='registry', dependencyId='bundle', state='blocked', reasonCode='REGISTRY_REVOKED', recoverable=False, requiredAction='Current registration required')\\n    c._installed = SimpleNamespace(get_readiness=lambda **kw: result.model_copy(update={'item':result.item.model_copy(update={'blockers':[*result.item.blockers,blocker]})}))\\n    with pytest.raises(AssetNotFoundError): c.get_readiness(**ARGS)\\n\", \".evidence/qyh-native-readmodel-installed-gate-20261013/review-material-2.txt\": \"# 下一波：原八台只读read-model安装门调查\\n\\nRules：用户初心、231、上位双侧增长产品与恢复方案。八页可点击不是首链；现有404必须调查真实原因，不因预算未续期而把所有读取归因预算。已有签名ACTIVE5八模块明确授ecommerce.workshop.read（原投影没有DATA_SCOPE_NOT_GRANTED）；旧CatalogDependency legacy-only排除所有当前runtime包。\\n\\n第1/8：复习上位产品与当前authority2011，代码预检已交付98642f8但不授预算/运行。第2/8文件计划：新增ecommerce_workshop_read_catalog.py（仅若审计证明GET可独立于runtime执行，以原签名/安装/真实data-scope为读取条件），routers/ecommerce_workshop.py只允许明确审核的GET注入ReadCatalogDependency；新增test_ecommerce_workshop_read_catalog.py证明无身份/租户/锁/签名/数据scope拒绝，POST继续旧业务依赖及原执行门。\\n\\n先在同轮实际审计8个GET与默认reader构造：仅AOS当前已保留数据/明确unknown来源，禁止触发外部商城/Provider/Source探测；如果某reader可能外部请求，该route不纳入本波。先限定root8，辅助/private GET另逐项审计。不改变legacy来源谓词、不伪造runtime-ready/UI session/Owner/审批，不返回mock数据或把None转0。写代码前要记录具体审计与细化方案，再RED、最小实现、专项/累计、真实页面、独立冻结代码复审、Delivery/上下文及下一波。目标是让真实安装状态与read-model缺口正确反映，真实数据/天然首链仍独立验收。\\n\\n## 第2/8细化（2026-10-13，本轮规则与候选）\\nRules：已复习 aos-engineering-delivery、当前01/06 authority2011、231上下文与产品双侧增长方案。唯一m1写者；Task同owner Lease至10:47UTC有效；用户dirty不覆盖；本aos-2不重启。候选一：已登记GET安装读取门（无真实库写、无外部请求依赖）；候选二：已登记预算续期有界consumer（需原真实maker/checker与当前锁再验，不能复用安装审批）。本轮选择候选一。\\n\\n具体目录：services/aos-api/aos_api/ecommerce_workshop_read_catalog.py；services/aos-api/tests/test_ecommerce_workshop_read_catalog.py；后续审计完成才改services/aos-api/aos_api/routers/ecommerce_workshop.py。\\n\\n已实际复核：Analyst SourceReadiness只读本库meta_pipeline/meta_source/meta_schedule_run/ecom_object/obj_instance/capability及本地policy文件，无源探测；Customer读本库保留自然run/count；ContentCampaign read_snapshot使用read_connect_factory；Creator各list使用read_connect_factory；TaskCockpit read_core显式REPEATABLE READ READ ONLY。Media根read还经过lifecycle、publish._compose及多个list/get，仍需对其完整传递调用作审计；Operations各本库reader亦需补全。不能因方法名为read就宣称无副作用。\\n\\n本轮先实现独立适配器，尚不接任何HTTP route：原legacy get_readiness成功原样保留；仅AssetNotFound才查显式selected安装目录；完整复用原签名/锁/hash/角色/marking/撤销检查；selected fallback要求每个声明dataScope都有本安装同lock的DataScopeGrant，禁止只凭module.permissions宣称授权；非object/capability/aip未知或INSTALLED_ASSET_READONLY的其他blocker均拒绝；不提升disabled/readiness、不缓存安装。返回not found隐去未授权模块；原目录、POST及服务reader无改动。专项包括真实本地bundle解析fixture、无scope、撤销、跨tenant、hash漂移、legacy错误不回退和legacy成功不改变。此阶段只证明读取门候选，不证明HTTP数据/8页面/首链。最终route仍待安全审计和单独RED。\\n\\n第3/8：8缺模块RED已复现后新增纯读取适配器；第4/8：专项与原目录、runtime目录及原HTTP邻接结果见verification-candidate.json。路由字节与HEAD一致，未激活GET、未重启、未改真库、未运行Provider。Media committed HEAD传递调用已按精确方法/hash提取，仍需复核_bundle/_view/_decision/_job等递归helper，不可把调用提取当无效果证明。第5～8步及HTTP接线仍待继续；Task保持ACTIVE，不声称页面或业务恢复完成。\\n\", \".evidence/qyh-native-readmodel-installed-gate-20261013/review-material-3.txt\": \"..................................................................       [100%]\\n=============================== warnings summary ===============================\\nservices/aos-api/aos_api/media_set.py:70\\n  /Users/ddt/work/projects/ai_agent/aos-platform/services/aos-api/aos_api/media_set.py:70: UserWarning: Field name \\\"schema\\\" in \\\"MediaSet\\\" shadows an attribute in parent \\\"BaseModel\\\"\\n    class MediaSet(BaseModel):\\n\\nservices/aos-api/aos_api/materialized_access_control.py:130\\n  /Users/ddt/work/projects/ai_agent/aos-platform/services/aos-api/aos_api/materialized_access_control.py:130: UserWarning: Field name \\\"schema\\\" in \\\"AgentTool\\\" shadows an attribute in parent \\\"BaseModel\\\"\\n    class AgentTool(BaseModel):\\n\\nservices/aos-api/aos_api/routers/materialized_access_control.py:83\\n  /Users/ddt/work/projects/ai_agent/aos-platform/services/aos-api/aos_api/routers/materialized_access_control.py:83: UserWarning: Field name \\\"schema\\\" in \\\"CreateAgentToolRequest\\\" shadows an attribute in parent \\\"BaseModel\\\"\\n    class CreateAgentToolRequest(BaseModel):\\n\\nservices/aos-api/aos_api/aip_logic_dry_run_executor.py:45\\n  /Users/ddt/work/projects/ai_agent/aos-platform/services/aos-api/aos_api/aip_logic_dry_run_executor.py:45: UserWarning: Field name \\\"schema\\\" in \\\"_InputConfig\\\" shadows an attribute in parent \\\"_Config\\\"\\n    class _InputConfig(_Config):\\n\\nservices/aos-api/aos_api/phase5_pipeline_engine.py:126\\n  /Users/ddt/work/projects/ai_agent/aos-platform/services/aos-api/aos_api/phase5_pipeline_engine.py:126: UserWarning: Field name \\\"schema\\\" in \\\"Dataset\\\" shadows an attribute in parent \\\"BaseModel\\\"\\n    class Dataset(BaseModel):\\n\\nservices/aos-api/aos_api/routers/phase5_datasets.py:32\\n  /Users/ddt/work/projects/ai_agent/aos-platform/services/aos-api/aos_api/routers/phase5_datasets.py:32: UserWarning: Field name \\\"schema\\\" in \\\"CreateDatasetRequest\\\" shadows an attribute in parent \\\"BaseModel\\\"\\n    class CreateDatasetRequest(BaseModel):\\n\\nservices/aos-api/.venv/lib/python3.11/site-packages/fastapi/testclient.py:1\\n  /Users/ddt/work/projects/ai_agent/aos-platform/services/aos-api/.venv/lib/python3.11/site-packages/fastapi/testclient.py:1: StarletteDeprecationWarning: Using `httpx` with `starlette.testclient` is deprecated; install `httpx2` instead.\\n    from starlette.testclient import TestClient as TestClient  # noqa\\n\\n-- Docs: https://docs.pytest.org/en/stable/how-to/capture-warnings.html\\n66 passed, 7 warnings in 4.49s\\n\", \".evidence/qyh-native-readmodel-installed-gate-20261013/review-material-4.txt\": \"\\\"\\\"\\\"Signed installed-asset viewing, separate from business/runtime admission.\\\"\\\"\\\"\\nfrom __future__ import annotations\\nfrom uuid import UUID\\n\\nfrom aos_api.ecommerce_workshop_catalog import EcommerceWorkshopCatalog\\nfrom aos_api.ecommerce_workshop_contracts import (\\n    WorkshopDependencyState, WorkshopDependencyType, WorkshopReadiness,\\n    WorkshopReadinessBlocker,\\n)\\n\\n\\nclass _SelectedInstalledSource:\\n    def __init__(self, source, *, installation_id: str, org_id: str, project_id: str):\\n        if str(UUID(installation_id)) != installation_id:\\n            raise ValueError('Canonical installation UUID required')\\n        if not org_id.strip() or not project_id.strip():\\n            raise ValueError('Explicit tenant required')\\n        self.source = source\\n        self.installation_id = installation_id\\n        self.org_id = org_id\\n        self.project_id = project_id\\n\\n    def read_active_bundles(self, *, org_id, project_id, markings):\\n        if (org_id, project_id) != (self.org_id, self.project_id):\\n            return ()\\n        # This remains candidate discovery. It grants no runtime/UI session.\\n        rows = self.source.read_runtime_candidate_bundles(\\n            org_id=org_id, project_id=project_id, markings=markings)\\n        return tuple(row for row in rows if row.installation_id == self.installation_id)\\n\\n\\nclass InstalledReadonlyWorkshopCatalog(EcommerceWorkshopCatalog):\\n    \\\"\\\"\\\"Reuse exact lock/signature/artifact/permission projection; always disabled.\\\"\\\"\\\"\\n    def __init__(self, *, source, loader, installation_id, org_id, project_id, clock=None):\\n        selected = _SelectedInstalledSource(source, installation_id=installation_id,\\n            org_id=org_id, project_id=project_id)\\n        super().__init__(source=selected, loader=loader, clock=clock)\\n\\n    def _project_modules(self, **kwargs):\\n        modules, cutoff = super()._project_modules(**kwargs)\\n        for module in modules:\\n            module.readiness = WorkshopReadiness.DISABLED\\n            module.blockers.append(WorkshopReadinessBlocker(\\n                dependencyType=WorkshopDependencyType.INSTALLATION,\\n                dependencyId=module.installation_ref.installation_id,\\n                state=WorkshopDependencyState.UNKNOWN,\\n                reasonCode='INSTALLED_ASSET_READONLY', recoverable=True,\\n                requiredAction='已安装页面可只读查看；业务执行仍须完成正式运行准入。'))\\n        return modules, cutoff\\n\\n\\nclass _EmptySource:\\n    def read_active_bundles(self, **kwargs):\\n        return ()\\n\\n\\ndef build_installed_readonly_catalog():\\n    \\\"\\\"\\\"Explicit server configuration; absent configuration discovers nothing.\\\"\\\"\\\"\\n    import json\\n    import os\\n    from pathlib import Path\\n    from aos_api.asset_registry.control_wiring import _allowlist_roots, _configured_trust_roots\\n    from aos_api.asset_registry.errors import RegistryIntegrityCorruptError\\n    from aos_api.asset_registry.manifest_loader import ManifestLoader\\n    from aos_api.asset_registry.workshop_catalog_source import PostgresWorkshopCatalogSource\\n    from aos_api.db import connect_read_only\\n\\n    raw = os.getenv('AOS_INSTALLED_READONLY_CATALOG')\\n    if not raw:\\n        return EcommerceWorkshopCatalog(source=_EmptySource(), loader=None)\\n    try:\\n        config = json.loads(raw)\\n        if not isinstance(config, dict) or set(config) != {'installationId', 'orgId', 'projectId'}:\\n            raise ValueError('Explicit bounded configuration required')\\n        if not all(isinstance(value, str) and value.strip() == value and value for value in config.values()):\\n            raise ValueError('Canonical configuration required')\\n        if not os.getenv('AOS_LOCAL_MANAGEMENT_OIDC_CONFIG') or not os.getenv('AOS_BUNDLE_ROOT'):\\n            raise ValueError('Management identity and signed source required')\\n        trust = _configured_trust_roots()\\n        if trust is None:\\n            raise ValueError('Explicit trust roots required')\\n        return InstalledReadonlyWorkshopCatalog(\\n            source=PostgresWorkshopCatalogSource(lambda: connect_read_only(inherit_scope=False)),\\n            loader=ManifestLoader(_allowlist_roots(repository_root=Path(__file__).resolve().parents[3]), trust_roots=trust),\\n            installation_id=config['installationId'], org_id=config['orgId'], project_id=config['projectId'])\\n    except (ValueError, TypeError, KeyError):\\n        raise RegistryIntegrityCorruptError() from None\\n\"}, \"claims\": [\"C1: The candidate preserves successful legacy admission and rejects fallback after a legacy integrity error. Its installed fallback requires every declared data scope to have a matching current lock grant; it preserves disabled readiness.\", \"C2: The isolated candidate and adjacent catalog/HTTP regression run passed 66 tests. No router was changed and no HTTP activation, real database write, runtime admission or business completion is claimed.\"]}"}],"timestamp":1791880874925}}
